/* Single shared resolver used by the postcode lookup (live + offline) AND
   the manual council-search field, so all three paths behave consistently.
   Given a real ONS council name, returns our internal pilot council id if
   it's one of the 12 we have local scheme data for, or "other" plus the
   real name otherwise. */
function resolveCouncilByName(realName) {
  if (!realName) return null;
  const pilotId = ADMIN_DISTRICT_TO_COUNCIL[realName.toLowerCase()];
  return {
    id: pilotId || "other",
    isPilot: !!pilotId,
    realName
  };
}

/* Looks up which council a postcode falls in using postcodes.io, a free,
   open UK postcode API (no key required). Only the postcode itself is
   sent — nothing else the user has entered leaves the browser.
   A 6-second timeout stops a slow/blocked connection hanging the UI. */
async function lookupCouncilByPostcode(rawPostcode) {
  const clean = (rawPostcode || "").trim().replace(/\s+/g, "");
  if (!clean) return { status: "empty" };
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 6000);
  try {
    const res = await fetch("https://api.postcodes.io/postcodes/" + encodeURIComponent(clean), {
      signal: controller.signal
    });
    clearTimeout(timeout);
    if (!res.ok) return { status: "not_found" };
    const data = await res.json();
    const district = data && data.result && data.result.admin_district;
    if (!district) return { status: "not_found" };
    const councilId = ADMIN_DISTRICT_TO_COUNCIL[district.toLowerCase()];
    if (councilId) return { status: "matched", councilId, districtName: district };
    return { status: "not_covered", districtName: district };
  } catch (e) {
    clearTimeout(timeout);
    return { status: "error" };
  }
}

