function parsePostcodeParts(rawPostcode) {
  const clean = (rawPostcode || "").trim().toUpperCase().replace(/\s+/g, "");
  if (!clean) return null;
  // Try treating the whole string as just an outward code (e.g. "LS1", "SW1A")
  if (/^[A-Z]{1,2}\d[A-Z\d]?$/.test(clean)) {
    return { outward: clean, sector: null };
  }
  // Otherwise assume a full postcode: the outward code is everything but
  // the last 3 characters (a digit followed by 2 letters, e.g. "1AA").
  if (clean.length > 3) {
    const outward = clean.slice(0, clean.length - 3);
    const inwardFirst = clean.slice(clean.length - 3, clean.length - 2);
    if (/^[A-Z]{1,2}\d[A-Z\d]?$/.test(outward)) {
      return { outward, sector: outward + " " + inwardFirst };
    }
  }
  return null;
}

/* Returns a real ONS local authority name (string), or null if the
   postcode/outcode isn't recognised. Sector-level match (finer) is tried
   first where available, falling back to the outcode-level majority. */
function matchOfflineCouncil(rawPostcode) {
  const parts = parsePostcodeParts(rawPostcode);
  if (!parts) return null;
  if (parts.sector && ENGLAND_POSTCODE_DATA.sectors[parts.sector]) {
    return ENGLAND_POSTCODE_DATA.sectors[parts.sector];
  }
  if (ENGLAND_POSTCODE_DATA.outcodes[parts.outward]) {
    return ENGLAND_POSTCODE_DATA.outcodes[parts.outward];
  }
  return null;
}

